def minimumTimeToInitialState(word: str, k: int) -> int:
    n = len(word)
    Z = [0] * n
    Z[0] = n
    l = r = 0
    for i in range(1, n):
        if i < r:
            Z[i] = min(r - i, Z[i - l])
        while i + Z[i] < n and word[Z[i]] == word[i + Z[i]]:
            Z[i] += 1
        if i + Z[i] > r:
            l, r = i, i + Z[i]
    t = 1
    while t * k < n:
        if Z[t * k] >= n - t * k:
            return t
        t += 1
    return t
